import math

def f(x):
    return x**3 + 4*x**2 - 3*x + 8

def fp(x):
    return 3*x**2 + 8*x - 3

def newton_step(x):
    return x - f(x)/fp(x)

x = -5.0
seq = [x]
for i in range(20):
    x_next = round(newton_step(x), 4)
    seq.append(x_next)
    if x_next == x:
        print("converged at n=", i, "x_n=", x, "x_{n+1}=", x_next)
        break
    x = x_next

print(seq)
